 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    marker_row = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    marker_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    vals = [v for row in grid for v in row if v != 2]
    background = max(set(vals), key=vals.count)

    if marker_col is not None:
        axis = (w + 1) // 2
        marker_side = 1 if marker_col > axis else -1
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color not in (background, 2) and (c - axis) * marker_side < 0:
                    out[r][c] = background
                    target = 2 * axis - c
                    if 0 <= target < w and grid[r][target] != 2:
                        out[r][target] = color
        if 0 <= axis < w:
            for r in range(h):
                if grid[r][axis] != 2:
                    out[r][axis] = 8
    elif marker_row is not None:
        axis = (h + 1) // 2
        marker_side = 1 if marker_row > axis else -1
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color not in (background, 2) and (r - axis) * marker_side < 0:
                    out[r][c] = background
                    target = 2 * axis - r
                    if 0 <= target < h and grid[target][c] != 2:
                        out[target][c] = color
        if 0 <= axis < h:
            out[axis] = [8 if v != 2 else 2 for v in grid[axis]]
    return out

if __name__ == '__main__':
