    test[19] = [6,6,6,6,6,6,6,6,6,6,1,1]
    test[20] = [6,6,6,6,6,6,6,1,1,1,1,1]
    test[21] = [6,6,6,6,6,6,6,6,1,1,1,1]
    test[24] = [2] * 12
    print(transform(test))
