 "content": "def transform(grid):
    """Shift the non-background pattern across the center divider toward a 2 stripe."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker_row = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    marker_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    vals = [v for row in grid for v in row if v != 2]
    background = max(set(vals), key=vals.count)
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (2, background)]

    if marker_col is not None:
        axis = w // 2
        # The complete pattern is shifted toward the 2 stripe by the distance
        # needed to place its nearest bounding-box edge at the divider.
        if cells:
            cmin = min(c for _, c, _ in cells)
            cmax = max(c for _, c, _ in cells)
            if marker_col > axis and cmax < axis:
                shift = axis - cmax
            elif marker_col < axis and cmin > axis:
                shift = axis - cmin
            else:
                shift = 0
            if shift:
                for r, c, _ in cells:
                    out[r][c] = background
                for r, c, color in cells:
                    nc = c + shift
                    if 0 <= nc < w and grid[r][nc] != 2:
                        out[r][nc] = color
        for r in range(h):
            if grid[r][axis] != 2:
                out[r][axis] = 8

    elif marker_row is not None:
        axis = h // 2
        if cells:
            rmin = min(r for r, _, _ in cells)
            rmax = max(r for r, _, _ in cells)
            if marker_row > axis and rmax < axis:
                shift = axis - rmax
            elif marker_row < axis and rmin > axis:
                shift = axis - rmin
            else:
                shift = 0
            if shift:
                for r, c, _ in cells:
                    out[r][c] = background
                for r, c, color in cells:
                    nr = r + shift
                    if 0 <= nr < h and grid[nr][c] != 2:
                        out[nr][c] = color
        out[axis] = [2 if v == 2 else 8 for v in grid[axis]]
    return out

if __name__ == '__main__':
