    background = max(set(values), key=values.count)
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (2, background)]
    if not cells:
        return out

    if marker_col is not None:
        divider = min(w - 1, w // 2 + 1)
        cmin = min(c for _, c, _ in cells)
        cmax = max(c for _, c, _ in cells)
        if marker_col > divider and cmax < divider:
            shift = divider + 1 - cmin
        elif marker_col < divider and cmin > divider:
            shift = divider - 1 - cmax
        else:
            shift = 0
        if shift:
            for r, c, _ in cells:
                out[r][c] = background
            for r, c, color in cells:
                nc = c + shift
                if 0 <= nc < w and grid[r][nc] != 2:
                    out[r][nc] = color
        for r in range(h):
            if grid[r][divider] != 2:
                out[r][divider] = 8

    elif marker_row is not None:
        divider = min(h - 1, h // 2 + 1)
        rmin = min(r for r, _, _ in cells)
        rmax = max(r for r, _, _ in cells)
        if marker_row > divider and rmax < divider:
            shift = divider + 1 - rmin
        elif marker_row < divider and rmin > divider:
            shift = divider - 1 - rmax
        else:
            shift = 0
        if shift:
            for r, c, _ in cells:
                out[r][c] = background
            for r, c, color in cells:
                nr = r + shift
                if 0 <= nr < h and grid[nr][c] != 2:
                    out[nr][c] = color
        for c in range(w):
            if grid[divider][c] != 2:
                out[divider][c] = 8
    return out

