    out = [row[:] for row in grid]

    stripe_row = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    stripe_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    nonstripe = [v for row in grid for v in row if v != 2]
    if not nonstripe:
        return out
    background = max(set(nonstripe), key=nonstripe.count)
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (2, background)]
    if not cells:
        return out

    if stripe_row is not None:
        rmin = min(r for r, _, _ in cells)
        rmax = max(r for r, _, _ in cells)
        if stripe_row > rmax:
            shift = stripe_row - 1 - rmax
            divider = rmin + shift - 1
        else:
            shift = stripe_row + 1 - rmin
            divider = rmax + shift + 1
        for r, c, _ in cells:
            out[r][c] = background
        for r, c, color in cells:
            nr = r + shift
            if 0 <= nr < h:
                out[nr][c] = color
        if 0 <= divider < h:
            out[divider] = [8] * w

    elif stripe_col is not None:
        cmin = min(c for _, c, _ in cells)
        cmax = max(c for _, c, _ in cells)
        if stripe_col > cmax:
            shift = stripe_col - 1 - cmax
            divider = cmin + shift - 1
        else:
            shift = stripe_col + 1 - cmin
            divider = cmax + shift + 1
        for r, c, _ in cells:
            out[r][c] = background
        for r, c, color in cells:
            nc = c + shift
            if 0 <= nc < w:
                out[r][nc] = color
        if 0 <= divider < w:
            for r in range(h):
